"use strict";
function* execute(action,input,state){state=state||{};if(action==="metadata")action="detail";var result=yield* sourceExecute(action,input,state);result=result||{};if(result.error)throw new Error(result.error);if(result.drama)result.drama=normalizeDrama(result.drama);if(Array.isArray(result.items))result.items=result.items.map(function(row){if(row.drama){row.drama=normalizeDrama(row.drama);return row;}return row.sourceId?normalizeDrama(row):row;});result.state=state;return result;}
function normalizeDrama(row){return Object.assign({},row,{description:String(first(row,["description","desc","intro"])),episodes:Number(first(row,["episodes","totalEpisode","episodeCount"],0))||0,category:String(first(row,["category","categoryName"])),sourceId:String(row.sourceId||""),title:String(first(row,["title","name"],"未命名")),tags:array(row.tags).filter(function(value){return typeof value==="string";})});}
function query(params) { return Object.keys(params).sort().map(function(key){return encodeURIComponent(key)+"="+encodeURIComponent(String(params[key])).replace(/%20/g,"+");}).join("&"); }
function first(object,keys,fallback){for(var i=0;i<keys.length;i++){var value=object&&object[keys[i]];if(value!==undefined&&value!==null&&value!=="")return value;}return fallback===undefined?"":fallback;}
function array(value){return Array.isArray(value)?value:[];}
function url(value){var values=array(value&&value.url_list);for(var i=0;i<values.length;i++){if(/^https:\/\//.test(values[i]))return values[i];}return typeof value==="string"&&/^https:\/\//.test(value)?value:"";}
function* http(address,options){options=options||{};var response=yield {type:"http",url:address,method:options.method||"GET",headers:options.headers||{},body:options.body,credential:!!options.credential,sign:!!options.sign};if(!response||response.status!==200){var error=new Error("HTTP failed");error.sourceError="http";error.httpStatus=response&&response.status||0;throw error;}return response.text;}
function* json(address,options){var data=JSON.parse(yield* http(address,options));if(data.status_code&&data.status_code!==0)throw new Error("API status");return data;}
function empty(){return {items:[],hasMore:false};}
function assignment(body,pattern){var match=pattern.exec(body);if(!match)return null;var start=match.index+match[0].length;while(/\s/.test(body[start]||"")&&start<body.length)start++;var depth=0,quoted=false,escaped=false;for(var i=start;i<body.length;i++){var c=body[i];if(escaped){escaped=false;continue;}if(quoted&&c==='\\'){escaped=true;continue;}if(c==='"'){quoted=!quoted;continue;}if(quoted)continue;if(c==='{'||c==='[')depth++;else if(c==='}'||c===']'){if(--depth===0)return JSON.parse(body.slice(start,i+1));}}throw new Error("页面参数不完整");}
function nodes(body,selector){return Array.from(htmlSelect(body,selector));}
function nodeText(body,selector){var row=nodes(body,selector)[0];return row?String(row.text).replace(/\s+/g," ").trim():"";}
function attr(body,selector,key){var row=nodes(body,selector)[0];return row?row.attributes[key]||"":"";}
function single(drama,chapter){return {drama:drama,chapters:[chapter||{id:drama.sourceId,title:"播放",currentEpisode:1}]};}
function select(choices,height){choices=choices.filter(function(value){return value.url&&/^https:\/\//.test(value.url);}).sort(function(a,b){return b.height-a.height;});if(!choices.length)throw new Error("No playable media");var selected=height?choices.find(function(value){return value.height<=height;})||choices[choices.length-1]:choices[0];return {url:selected.url,quality:selected.height||0,qualities:choices.map(function(value){return value.height||0;}),headers:selected.headers||{},decryptionKey:selected.key||"",variants:[selected].concat(choices.filter(function(value){return value.url!==selected.url;})).slice(0,16).map(function(value){return {url:value.url,quality:value.height||0,headers:value.headers||{},decryptionKey:value.key||""};})};}

var soraniBase="https://api.sorani.cc/sorani-cms/api";
function* soraniRequest(route,params){var value=yield* json(soraniBase+route+(params?"?"+query(params):""),{headers:{"User-Agent":"Mozilla/5.0","Referer":"https://www.sorani.net/","Origin":"https://www.sorani.net"}});if(value.code!==undefined&&value.code!==0&&value.code!==200)throw new Error("青空次元接口返回错误");return value.data===undefined?value:value.data;}
function soraniDrama(row){var id=String(first(row,["id","videoId"])),title=String(first(row,["title","name","videoTitle"]));if(!/^\d+$/.test(id)||!title)throw new Error("青空次元剧集信息无效");var cover=String(first(row,["cover","coverLarge","coverSmall","coverThumb","backgroundImage"]));if(cover.indexOf("//")===0)cover="https:"+cover;else if(cover.indexOf("/")===0)cover="https://www.sorani.net"+cover;return {id:"sorani:"+id,source:"sorani",sourceId:id,title:title,description:String(first(row,["summary","description","intro","desc"])),cover:cover,episodes:Number(first(row,["episodeCount","totalEpisode","total"],0)),category:String(first(row,["categoryName","category"],"番剧")),tags:array(row.tags||row.tagList).map(String)};}
function* sourceExecute(action,input,state){
 if(action==="categories")return {items:[{id:"1",name:"TV番剧"},{id:"2",name:"剧场动画"},{id:"5",name:"特摄剧场"}]};
 if(action==="catalog"||action==="search"||action==="check") {var page=Number(input.page)||1,params={page:page,size:24};if(input.query)params.keyword=input.query;else if(input.category)params.categoryId=input.category;var result=yield* soraniRequest(input.query?"/video/search":"/video",params),rows=Array.isArray(result)?result:first(result,["records","list","items","rows"],null);if(!Array.isArray(rows)||rows.length>500)throw new Error("青空次元目录格式无效");var total=Number(result.total),pages=Number.isFinite(total)?Math.ceil(total/24):0;return {items:rows.map(soraniDrama),page:page,totalPages:pages,hasMore:pages?page<pages:rows.length>=24,count:rows.length};}
 var drama=input.drama||{},id=String(drama.sourceId||"" );if(!/^\d+$/.test(id))throw new Error("青空次元剧集标识无效");
 if(action==="detail"||action==="metadata") {var row=yield* soraniRequest("/video/"+id),value=soraniDrama(row);if(value.sourceId!==id||!Array.isArray(row.episodes)||row.episodes.length>10000)throw new Error("青空次元分集目录无效");var seen={},orders={},chapters=row.episodes.filter(function(ep){return ep.enabled!==false;}).map(function(ep,index){var eid=String(first(ep,["episodeId","id"])),order=Number(ep.episodeOrder)||index+1;if(!/^\d+$/.test(eid)||seen[eid]||orders[order])throw new Error("青空次元分集重复或无效");seen[eid]=orders[order]=true;return {id:"sorani:"+id+":"+eid,episodeId:eid,source:"sorani",title:String(first(ep,["episodeLabel","title","displayTitle"],"第 "+order+" 集")),currentEpisode:order};}).sort(function(a,b){return a.currentEpisode-b.currentEpisode;});return {drama:value,chapters:chapters};}
 if(action==="resolve") {var ep=input.chapter||{},eid=String(ep.episodeId||String(ep.id||"").split(":").pop());if(!/^\d+$/.test(eid))throw new Error("青空次元分集标识无效");var playback=yield* soraniRequest("/video/episode/"+eid+"/play",{lineCode:"anime_jp_m3u8"}),address=String(first(playback,["playUrl","url"]));if(!/^https:\/\//.test(address))throw new Error("青空次元暂无有效播放地址");return {url:address,quality:0,qualities:[],headers:{Referer:"https://www.sorani.net/"}};}
 throw new Error("青空次元不支持此操作");
}
